/// Name for `id`, or an empty view when the sheet does not carry it.
[[nodiscard]] constexpr std::string_view territory_name(uint32_t id) noexcept {
    const auto it = std::lower_bound(
        TERRITORY_TABLE.begin(), TERRITORY_TABLE.end(), id,
        [](const TerritoryEntry& entry, uint32_t value) { return entry.id < value; });
    if (it != TERRITORY_TABLE.end() && it->id == id) {
        return it->name;
    }
    return {};
}

